type: http
name: pushover
log_level: debug
url: https://api.pushover.net/1/messages.json
method: POST
headers:
  Content-Type: application/json
format: |-
  {{range . -}}{{$alert := . -}}{{range .Decisions -}}{
    "token": "{{ env "CROWDSEC_PUSHOVER_TOKEN" }}",
    "user": "{{ env "PUSHOVER_USER_KEY" }}",
    "title": "🚨 CrowdSec Alert: {{.Value}}",
    "html": "1",
    "url": "https://www.virustotal.com/gui/ip-address/{{.Value}}",
    "url_title": "View in VirusTotal",
    "message": "
  <b>🌐 Target Information:</b>
  • <b>IP Address:</b> {{.Value}}
  {{- $domains := GetMeta $alert "target_fqdn" | uniq | join ", "}}{{if ne $domains ""}}
  • <b>Domain(s):</b> {{$domains}}{{end}}
  {{- $paths := GetMeta $alert "http_path" | uniq | join ", "}}{{if ne $paths ""}}
  • <b>Path(s):</b> {{$paths}}{{end}}

  <b>🛡️ Action Taken:</b>
  • <b>Type:</b> {{.Type | title}}
  • <b>Duration:</b> {{.Duration}}
  • <b>Scenario:</b> {{.Scenario}}
  • <b>Timestamp:</b> {{$alert.StartAt}}
  • <b>Event Count:</b> {{len $alert.Events}}

  <b>📊 Request Details:</b>
  {{- $methods := GetMeta $alert "http_verb" | uniq | join ", "}}{{if ne $methods ""}}
  • <b>Method(s):</b> {{$methods}}{{end}}
  {{- $statuses := GetMeta $alert "http_status" | uniq | join ", "}}{{if ne $statuses ""}}
  • <b>Status(es):</b> {{$statuses}}{{end}}
  {{- $agents := GetMeta $alert "http_user_agent" | uniq}}{{if $agents}}{{if le (len $agents) 3}}
  • <b>User Agent(s):</b> {{$agents | join ", "}}{{else}}
  • <b>User Agents:</b> {{len $agents}} unique agents{{end}}{{end}}

  <b>🌍 Geographic Info:</b>
  {{- if $alert.Source.Cn}}
  • <b>Country:</b> {{$alert.Source.Cn}}{{end}}
  {{- $asnOrgs := GetMeta $alert "ASNOrg" | uniq | join ", "}}{{if ne $asnOrgs ""}}
  • <b>ASN:</b> {{$asnOrgs}}{{end}}

  <b>🔗 Investigation Links:</b>
  • <a href=\"https://www.abuseipdb.com/check/{{.Value}}\">🚨 AbuseIPDB</a>
  • <a href=\"https://ipinfo.io/{{.Value}}\">🌍 IPinfo</a>
  {{end}}{{end}}"
  }

server {
    listen 80;
    server_name _;
    root /var/www/html;
    index index.html;
    real_ip_header X-Forwarded-For;
    set_real_ip_from 10.42.0.0/16;
    set_real_ip_from 192.168.42.0/24;
    location / {
        try_files $uri $uri/ =404;
    }
}

